import java.util.*;class Solution{int[]pick(int[]a,int k){int[]s=new int[k];int top=0,drop=a.length-k;for(int x:a){while(drop>0&&top>0&&s[top-1]<x){top--;drop--;}if(top<k)s[top++]=x;else drop--;}return s;}boolean ge(int[]a,int i,int[]b,int j){while(i<a.length&&j<b.length&&a[i]==b[j]){i++;j++;}return j==b.length||(i<a.length&&a[i]>b[j]);}int[]merge(int[]a,int[]b){int[]r=new int[a.length+b.length];int i=0,j=0;for(int k=0;k<r.length;k++)r[k]=ge(a,i,b,j)?a[i++]:b[j++];return r;}public int[] maxNumber(int[]a,int[]b,int k){int[]best=new int[k];boolean set=false;for(int i=Math.max(0,k-b.length);i<=Math.min(k,a.length);i++){int[]r=merge(pick(a,i),pick(b,k-i));if(!set||ge(r,0,best,0)){best=r;set=true;}}return best;}}
